import { resolve } from 'node:path';
import { Policy } from './policy.mjs';
import { runProcess } from './process.mjs';
import { discoverCapabilities } from './capabilities.mjs';
import { inspectArtifact } from './artifact.mjs';
import { KnowledgeFolder } from './knowledge-folder.mjs';
import { inspectRepository, createDetachedWorktree } from '../adapters/git.mjs';
import { buildCiCommand } from '../adapters/ci.mjs';
import { buildContainerRun } from '../adapters/container.mjs';
import { buildAdbCommand, buildEmulatorCommand } from '../adapters/android.mjs';
import { detectHostProfile } from './host.mjs';
import { VoiceConciergeRuntime } from '../communications/voice-concierge.mjs';

function parseRoots(value) {
  if (!value) return [process.cwd()];
  return value.split(process.platform === 'win32' ? ';' : ':').filter(Boolean).map((v) => resolve(v));
}

export class OmegaControlPlane {
  constructor({ workspaceRoots = parseRoots(process.env.OMEGA_WORKSPACE_ROOTS), policy, knowledgeRoot = process.env.OMEGA_KNOWLEDGE_ROOT } = {}) {
    this.workspaceRoots = workspaceRoots.map((root) => resolve(root));
    this.policy = policy ?? new Policy({ workspaceRoots: this.workspaceRoots });
    this.voiceConciergeRuntime = new VoiceConciergeRuntime();
    this.knowledgeRoot = knowledgeRoot ? resolve(knowledgeRoot) : null;
    this.knowledgeFolder = this.knowledgeRoot ? new KnowledgeFolder({ root: this.knowledgeRoot }) : null;
  }

  capabilities() {
    return discoverCapabilities();
  }

  hostInfo() {
    return { ...detectHostProfile(), workspaceRoots: [...this.workspaceRoots], knowledgeRoot: this.knowledgeRoot };
  }

  knowledgeInfo() {
    if (!this.knowledgeFolder) return { configured: false, readOnly: true, root: null };
    return this.knowledgeFolder.info().then((value) => ({ configured: true, ...value }));
  }

  knowledgeList(input = {}) {
    if (!this.knowledgeFolder) throw new Error('OMEGA_KNOWLEDGE_ROOT is not configured');
    return this.knowledgeFolder.list(input);
  }

  knowledgeRead(input = {}) {
    if (!this.knowledgeFolder) throw new Error('OMEGA_KNOWLEDGE_ROOT is not configured');
    return this.knowledgeFolder.read(input);
  }

  knowledgeSearch(input = {}) {
    if (!this.knowledgeFolder) throw new Error('OMEGA_KNOWLEDGE_ROOT is not configured');
    return this.knowledgeFolder.search(input);
  }

  terminalRun(input) {
    return runProcess({ ...input, source: 'terminal', policy: this.policy });
  }

  repositoryInspect(cwd) {
    return inspectRepository({ cwd, policy: this.policy });
  }

  sandboxCreate({ repository, destination, revision }) {
    return createDetachedWorktree({ repository, destination, revision, policy: this.policy });
  }

  async ci({ cwd, provider, action, limit, runId, workflow, ref }) {
    const argv = buildCiCommand({ provider, action, limit, runId, workflow, ref });
    const sideEffect = action === 'trigger' ? 'E' : 'R';
    return await runProcess({ argv, cwd, sideEffect, source: 'internal', policy: this.policy, timeoutMs: 120_000 });
  }

  async containerRun(input) {
    const plan = buildContainerRun(input);
    return await runProcess({ ...plan, source: 'project', policy: this.policy, timeoutMs: input.timeoutMs ?? 300_000, maxOutputBytes: input.maxOutputBytes ?? 2_097_152 });
  }

  async buildRun({ cwd, argv, timeoutMs = 600_000, maxOutputBytes = 4_194_304 }) {
    return await runProcess({ argv, cwd, sideEffect: 'L', source: 'project', policy: this.policy, timeoutMs, maxOutputBytes });
  }

  async verify({ cwd, checks, timeoutMs = 600_000 }) {
    if (!Array.isArray(checks) || checks.length === 0 || checks.length > 20) throw new Error('checks must contain between 1 and 20 commands');
    const results = [];
    for (const check of checks) {
      if (!Array.isArray(check.argv) || check.argv.length === 0) throw new Error('Each verification check requires argv');
      const result = await runProcess({ argv: check.argv, cwd, sideEffect: 'L', source: 'project', policy: this.policy, timeoutMs: check.timeoutMs ?? timeoutMs, maxOutputBytes: 2_097_152 });
      results.push({ name: check.name ?? check.argv.join(' '), ...result });
      if (result.exitCode !== 0) break;
    }
    return { passed: results.length === checks.length && results.every((item) => item.exitCode === 0), results };
  }

  async device({ cwd, kind = 'adb', ...input }) {
    if (kind === 'adb' && input.action === 'install') input.artifact = this.policy.assertPath(input.artifact);
    const argv = kind === 'emulator' ? buildEmulatorCommand(input) : buildAdbCommand(input);
    const mutationActions = new Set(['shell', 'install', 'start']);
    const sideEffect = mutationActions.has(input.action) ? 'L' : 'R';
    return await runProcess({ argv, cwd, sideEffect, source: mutationActions.has(input.action) ? 'project' : 'internal', policy: this.policy, timeoutMs: 180_000 });
  }

  voiceConcierge(input = {}) {
    return this.voiceConciergeRuntime.action(input);
  }

  artifactInspect(path) {
    return inspectArtifact({ path, workspaceRoots: this.workspaceRoots });
  }
}

import { lstat, readFile, readdir, realpath, stat } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { extname, relative, resolve, sep } from 'node:path';

const TEXT_EXTENSIONS = new Set([
  '.txt', '.md', '.markdown', '.html', '.htm', '.json', '.jsonl', '.csv', '.tsv',
  '.xml', '.yaml', '.yml', '.log', '.ini', '.toml', '.js', '.mjs', '.cjs', '.ts',
  '.tsx', '.jsx', '.py', '.java', '.kt', '.kts', '.go', '.rs', '.c', '.h', '.cpp',
  '.hpp', '.css', '.scss', '.sql', '.sh', '.bash', '.zsh'
]);

function inside(root, candidate) {
  return candidate === root || candidate.startsWith(root.endsWith(sep) ? root : `${root}${sep}`);
}

async function defaultPdfText({ path, maxBytes = 1_048_576 }) {
  return await new Promise((resolveText, reject) => {
    const child = spawn('pdftotext', ['-layout', '-nopgbrk', path, '-'], {
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: false
    });
    const out = [];
    const err = [];
    let bytes = 0;
    let truncated = false;

    child.stdout.on('data', (chunk) => {
      if (bytes >= maxBytes) {
        truncated = true;
        return;
      }
      const remaining = maxBytes - bytes;
      const slice = chunk.subarray(0, remaining);
      out.push(slice);
      bytes += slice.length;
      if (slice.length < chunk.length) truncated = true;
    });
    child.stderr.on('data', (chunk) => {
      const current = err.reduce((sum, item) => sum + item.length, 0);
      if (current < 65_536) err.push(chunk.subarray(0, Math.max(0, 65_536 - current)));
    });
    child.once('error', reject);
    child.once('close', (code) => {
      if (code !== 0) {
        reject(new Error(`pdftotext failed with exit code ${code}: ${Buffer.concat(err).toString('utf8').trim()}`));
        return;
      }
      resolveText({ text: Buffer.concat(out).toString('utf8'), truncated });
    });
  });
}

export class KnowledgeFolder {
  constructor({ root, pdfText = defaultPdfText } = {}) {
    if (!root) throw new Error('Knowledge root is required');
    this.root = resolve(root);
    this.pdfText = pdfText;
  }

  async canonicalRoot() {
    try {
      return await realpath(this.root);
    } catch {
      return this.root;
    }
  }

  async resolveExisting(input = '') {
    const root = await this.canonicalRoot();
    const lexical = resolve(root, input || '.');
    if (!inside(root, lexical)) throw new Error(`Path is outside knowledge root: ${input}`);
    let canonical;
    try {
      canonical = await realpath(lexical);
    } catch {
      throw new Error(`Knowledge path does not exist: ${input || '.'}`);
    }
    if (!inside(root, canonical)) throw new Error(`Path is outside knowledge root: ${input}`);
    return { root, canonical };
  }

  async info() {
    try {
      const { root, canonical } = await this.resolveExisting('');
      const s = await stat(canonical);
      return { root, exists: true, directory: s.isDirectory(), readOnly: true };
    } catch (error) {
      return { root: this.root, exists: false, directory: false, readOnly: true, error: error.message };
    }
  }

  async list({ path = '', recursive = false, limit = 500 } = {}) {
    if (!Number.isInteger(limit) || limit < 1 || limit > 10_000) {
      throw new Error('limit must be between 1 and 10000');
    }
    const { root, canonical } = await this.resolveExisting(path);
    const baseStat = await stat(canonical);
    if (!baseStat.isDirectory()) throw new Error('Knowledge list path is not a directory');
    const entries = [];

    const walk = async (dir) => {
      const items = await readdir(dir, { withFileTypes: true });
      items.sort((a, b) => a.name.localeCompare(b.name));
      for (const item of items) {
        if (entries.length >= limit) return;
        const absolute = resolve(dir, item.name);
        const rel = relative(root, absolute).split(sep).join('/');
        if (item.isSymbolicLink()) {
          entries.push({ path: rel, kind: 'symlink' });
          continue;
        }
        const s = await lstat(absolute);
        const kind = item.isDirectory() ? 'directory' : item.isFile() ? 'file' : 'other';
        entries.push({
          path: rel,
          kind,
          size: item.isFile() ? s.size : null,
          modifiedMs: s.mtimeMs,
          extension: item.isFile() ? extname(item.name).toLowerCase() : null
        });
        if (recursive && item.isDirectory()) await walk(absolute);
      }
    };

    await walk(canonical);
    return {
      root,
      path: path || '',
      recursive: Boolean(recursive),
      entries,
      truncated: entries.length >= limit
    };
  }

  async read({ path, offset = 0, maxBytes = 1_048_576 } = {}) {
    if (!path) throw new Error('path is required');
    if (!Number.isInteger(offset) || offset < 0) throw new Error('offset must be a non-negative integer');
    if (!Number.isInteger(maxBytes) || maxBytes < 1 || maxBytes > 8_388_608) {
      throw new Error('maxBytes must be between 1 and 8388608');
    }
    const { root, canonical } = await this.resolveExisting(path);
    const s = await stat(canonical);
    if (!s.isFile()) throw new Error('Knowledge read path is not a regular file');
    const extension = extname(canonical).toLowerCase();

    if (extension === '.pdf') {
      if (offset !== 0) throw new Error('PDF reads do not support byte offset; use maxBytes to bound extracted text');
      const extracted = await this.pdfText({ path: canonical, maxBytes });
      const value = typeof extracted === 'string'
        ? { text: extracted, truncated: Buffer.byteLength(extracted, 'utf8') >= maxBytes }
        : extracted;
      return {
        root,
        path: relative(root, canonical).split(sep).join('/'),
        format: 'pdf-text',
        text: value.text,
        offset: 0,
        nextOffset: null,
        truncated: Boolean(value.truncated),
        sourceSize: s.size
      };
    }

    if (!TEXT_EXTENSIONS.has(extension) && extension !== '') {
      throw new Error(`Unsupported knowledge file type: ${extension || '(none)'}`);
    }
    const data = await readFile(canonical);
    const start = Math.min(offset, data.length);
    const end = Math.min(start + maxBytes, data.length);
    return {
      root,
      path: relative(root, canonical).split(sep).join('/'),
      format: 'text',
      text: data.subarray(start, end).toString('utf8'),
      offset: start,
      nextOffset: end,
      truncated: end < data.length,
      sourceSize: data.length
    };
  }

  async search({ query, path = '', limit = 50, maxFiles = 500, maxBytesPerFile = 2_097_152 } = {}) {
    if (!query || !String(query).trim()) throw new Error('query is required');
    if (!Number.isInteger(limit) || limit < 1 || limit > 500) throw new Error('limit must be between 1 and 500');
    if (!Number.isInteger(maxFiles) || maxFiles < 1 || maxFiles > 5000) {
      throw new Error('maxFiles must be between 1 and 5000');
    }
    const listing = await this.list({ path, recursive: true, limit: maxFiles });
    const needle = String(query).toLowerCase();
    const matches = [];
    let scanned = 0;

    for (const entry of listing.entries) {
      if (matches.length >= limit) break;
      if (entry.kind !== 'file') continue;
      const extension = entry.extension ?? '';
      if (extension !== '.pdf' && !TEXT_EXTENSIONS.has(extension) && extension !== '') continue;
      scanned += 1;
      try {
        const doc = await this.read({ path: entry.path, maxBytes: maxBytesPerFile });
        const haystack = doc.text.toLowerCase();
        let index = 0;
        while (matches.length < limit) {
          const at = haystack.indexOf(needle, index);
          if (at === -1) break;
          const from = Math.max(0, at - 120);
          const to = Math.min(doc.text.length, at + needle.length + 180);
          matches.push({ path: entry.path, index: at, excerpt: doc.text.slice(from, to) });
          index = at + Math.max(needle.length, 1);
        }
      } catch (error) {
        matches.push({ path: entry.path, error: error.message, skipped: true });
        if (matches.length >= limit) break;
      }
    }

    return {
      query: String(query),
      path,
      matches,
      scannedFiles: scanned,
      listingTruncated: listing.truncated
    };
  }
}

import { McpServer } from '@modelcontextprotocol/server';
import { serveStdio } from '@modelcontextprotocol/server/stdio';
import { pathToFileURL } from 'node:url';
import * as z from 'zod/v4';
import { OmegaControlPlane } from './core/control-plane.mjs';

function success(value) {
  return {
    content: [{ type: 'text', text: JSON.stringify(value, null, 2) }],
    structuredContent: { result: value }
  };
}

function failure(error) {
  const value = {
    name: error?.name ?? 'Error',
    code: error?.code ?? null,
    message: error?.message ?? String(error)
  };
  return {
    content: [{ type: 'text', text: JSON.stringify({ error: value }, null, 2) }],
    structuredContent: { error: value },
    isError: true
  };
}

async function invoke(handler) {
  try {
    return success(await handler());
  } catch (error) {
    return failure(error);
  }
}

export function createServer(context = {}) {
  const plane = new OmegaControlPlane();
  const server = new McpServer({ name: 'omega-control-plane', version: '4.3.1' });

  server.registerTool(
    'omega_capabilities',
    {
      description: 'Discover the live OMEGA control-plane capabilities available on this machine.',
      inputSchema: z.object({})
    },
    async () => invoke(() => plane.capabilities())
  );

  server.registerTool(
    'omega_host_info',
    {
      description: 'Identify the execution host, including Android/Termux detection and configured workspace roots, without exposing environment secrets.',
      inputSchema: z.object({})
    },
    async () => invoke(() => plane.hostInfo())
  );

  server.registerTool(
    'omega_terminal_run',
    {
      description: 'Run one argv-based local process inside configured workspace roots. Restricted mode is read-only by default; no shell string is used.',
      inputSchema: z.object({
        argv: z.array(z.string().min(1)).min(1).max(128),
        cwd: z.string().min(1),
        sideEffect: z.enum(['R', 'L', 'E', 'H']).default('R'),
        timeoutMs: z.number().int().min(1).max(900000).default(120000),
        maxOutputBytes: z.number().int().min(1).max(16777216).default(1048576)
      })
    },
    async (input) => invoke(() => plane.terminalRun(input))
  );

  server.registerTool(
    'omega_knowledge_info',
    {
      description: 'Report whether the read-only phone knowledge folder is configured and accessible.',
      inputSchema: z.object({})
    },
    async () => invoke(() => plane.knowledgeInfo())
  );

  server.registerTool(
    'omega_knowledge_list',
    {
      description: 'List files and folders beneath the configured phone knowledge root without modifying them.',
      inputSchema: z.object({
        path: z.string().default(''),
        recursive: z.boolean().default(false),
        limit: z.number().int().min(1).max(10000).default(500)
      })
    },
    async (input) => invoke(() => plane.knowledgeList(input))
  );

  server.registerTool(
    'omega_knowledge_read',
    {
      description: 'Read a bounded slice of a text document or extract bounded text from a PDF inside the phone knowledge root.',
      inputSchema: z.object({
        path: z.string().min(1),
        offset: z.number().int().min(0).default(0),
        maxBytes: z.number().int().min(1).max(8388608).default(1048576)
      })
    },
    async (input) => invoke(() => plane.knowledgeRead(input))
  );

  server.registerTool(
    'omega_knowledge_search',
    {
      description: 'Search supported text and PDF files beneath the phone knowledge root and return bounded excerpts.',
      inputSchema: z.object({
        query: z.string().min(1),
        path: z.string().default(''),
        limit: z.number().int().min(1).max(500).default(50),
        maxFiles: z.number().int().min(1).max(5000).default(500),
        maxBytesPerFile: z.number().int().min(1).max(8388608).default(2097152)
      })
    },
    async (input) => invoke(() => plane.knowledgeSearch(input))
  );

  server.registerTool(
    'omega_repository_inspect',
    {
      description: 'Inspect repository identity, branch, HEAD, status and remotes without changing branch state.',
      inputSchema: z.object({ cwd: z.string().min(1) })
    },
    async ({ cwd }) => invoke(() => plane.repositoryInspect(cwd))
  );

  server.registerTool(
    'omega_sandbox_create',
    {
      description: 'Create a detached Git worktree sandbox while proving that the source branch and HEAD remain unchanged.',
      inputSchema: z.object({
        repository: z.string().min(1),
        destination: z.string().min(1),
        revision: z.string().min(1).default('HEAD')
      })
    },
    async (input) => invoke(() => plane.sandboxCreate(input))
  );

  server.registerTool(
    'omega_ci',
    {
      description: 'Inspect or trigger GitHub/GitLab CI through native CLIs. Triggering is an external mutation and is disabled unless explicitly enabled by policy.',
      inputSchema: z.object({
        cwd: z.string().min(1),
        provider: z.enum(['github', 'gitlab']),
        action: z.enum(['list', 'view', 'trigger']),
        limit: z.number().int().min(1).max(100).optional(),
        runId: z.union([z.string().min(1), z.number().int().positive()]).optional(),
        workflow: z.string().min(1).optional(),
        ref: z.string().min(1).optional()
      })
    },
    async (input) => invoke(() => plane.ci(input))
  );

  server.registerTool(
    'omega_container_run',
    {
      description: 'Run a bounded ephemeral Docker/Podman container with network disabled and a read-only workspace mount by default.',
      inputSchema: z.object({
        engine: z.enum(['docker', 'podman']).default('docker'),
        image: z.string().min(1).max(256),
        workspace: z.string().min(1),
        command: z.array(z.string()).min(1).max(128),
        writable: z.boolean().default(false),
        network: z.literal('none').default('none'),
        memory: z.string().regex(/^\d+[kKmMgG]$/).default('2g'),
        cpus: z.string().regex(/^\d+(?:\.\d+)?$/).default('2'),
        timeoutMs: z.number().int().min(1).max(900000).default(300000),
        maxOutputBytes: z.number().int().min(1).max(16777216).default(2097152),
        env: z.record(z.string(), z.string()).default({})
      })
    },
    async (input) => invoke(() => plane.containerRun(input))
  );

  server.registerTool(
    'omega_build_run',
    {
      description: 'Run a project build/test command under bounded execution. Project code execution is policy-gated.',
      inputSchema: z.object({
        cwd: z.string().min(1),
        argv: z.array(z.string().min(1)).min(1).max(128),
        timeoutMs: z.number().int().min(1).max(900000).default(600000),
        maxOutputBytes: z.number().int().min(1).max(16777216).default(4194304)
      })
    },
    async (input) => invoke(() => plane.buildRun(input))
  );

  server.registerTool(
    'omega_verify',
    {
      description: 'Run an ordered verification suite and stop on the first failing gate, returning evidence for every observed check.',
      inputSchema: z.object({
        cwd: z.string().min(1),
        timeoutMs: z.number().int().min(1).max(900000).default(600000),
        checks: z.array(z.object({
          name: z.string().min(1).optional(),
          argv: z.array(z.string().min(1)).min(1).max(128),
          timeoutMs: z.number().int().min(1).max(900000).optional()
        })).min(1).max(20)
      })
    },
    async (input) => invoke(() => plane.verify(input))
  );

  server.registerTool(
    'omega_device',
    {
      description: 'List or operate Android devices/emulators through ADB/emulator with explicit serial targeting for device mutation.',
      inputSchema: z.object({
        cwd: z.string().min(1),
        kind: z.enum(['adb', 'emulator']).default('adb'),
        action: z.enum(['list', 'shell', 'install', 'logcat', 'list-avds', 'start']),
        serial: z.string().min(1).optional(),
        command: z.array(z.string()).min(1).max(64).optional(),
        artifact: z.string().min(1).optional(),
        pid: z.number().int().positive().optional(),
        avd: z.string().min(1).optional(),
        wipeData: z.boolean().default(false),
        noWindow: z.boolean().default(false)
      })
    },
    async (input) => invoke(() => plane.device(input))
  );

  server.registerTool(
    'omega_artifact_inspect',
    {
      description: 'Verify a local artifact inside workspace roots and return immutable size, extension, timestamp and SHA-256 metadata.',
      inputSchema: z.object({ path: z.string().min(1) })
    },
    async ({ path }) => invoke(() => plane.artifactInspect(path))
  );


  server.registerTool(
    'omega_gateway_info',
    {
      description: 'Report the active OMEGA transport/runtime lane and normalized authenticated caller metadata without exposing bearer tokens or secrets.',
      inputSchema: z.object({})
    },
    async () => invoke(async () => ({
      transport: context.transport ?? 'stdio',
      authenticated: Boolean(context.authInfo),
      client_id: context.authInfo?.clientId ?? null,
      scopes: Array.isArray(context.authInfo?.scopes) ? [...context.authInfo.scopes] : [],
      cloud_run: Boolean(process.env.K_SERVICE),
      cloud_run_service: process.env.K_SERVICE ?? null,
      cloud_run_revision: process.env.K_REVISION ?? null,
      termux_secure_mcp_preserved: true,
      remote_mcp_endpoint: context.transport === 'remote-http' ? '/mcp' : null
    }))
  );

  return server;
}

export function startStdio() {
  const handle = serveStdio(() => createServer({ transport: 'stdio' }));
  console.error('OMEGA MCP control plane v4.3.1 running on stdio');
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.on(signal, () => {
      void handle.close().finally(() => process.exit(0));
    });
  }
  return handle;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  startStdio();
}

